1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Map;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Builds and interprets the owner {@code customerCode}, the single region-and-hash identity every
12	 * derived value (membership number, its check digit, the create audit line and the {@code locality})
13	 * now hangs off.
14	 *
15	 * <p>The code is {@code <REGION>-<HASH8>} where REGION is the {@link #region(Owner) region} derived
16	 * from the owner's postcode (falling back to the city, then {@code "UNKNOWN"}) and HASH8 is the first
17	 * eight upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)}. Sequence
18	 * numbers are no longer part of the identity, so the code depends only on the owner's own fields.
19	 */
20	public final class CustomerCodes {
21	
22	    /** Fixed city-to-region table (mirrors the read-only {@code locality} mapping). */
23	    private static final Map<String, String> CITY_REGION = Map.of(
24	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
25	
26	    /** Region -> inclusive 4-digit postcode range {low, high}. */
27	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
28	            "NSW", new int[] {2000, 2099},
29	            "VIC", new int[] {3000, 3099},
30	            "QLD", new int[] {4000, 4099});
31	
32	    private CustomerCodes() {
33	    }
34	
35	    /** Builds the {@code <REGION>-<HASH8>} customer code for the owner. */
36	    public static String build(Owner owner) {
37	        return region(owner) + "-" + hash8(owner);
38	    }
39	
40	    /**
41	     * The membership number {@code <customerCode>-M<YY>}, where YY is the last two digits of the
42	     * fiscal year (starting 1 July) containing the {@code registrationDate} (e.g. 'NSW-1A2B3C4D-M27').
43	     * Returns {@code null} when either the customer code or the registration date is absent (e.g.
44	     * legacy seed owners). The single definition the owner response and the create audit line share.
45	     */
46	    public static String membershipNumber(Owner owner) {
47	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
48	            return null;
49	        }
50	        return String.format("%s-M%02d", owner.getCustomerCode(),
51	                FiscalYears.of(owner.getRegistrationDate()) % 100);
52	    }
53	
54	    /**
55	     * The Luhn {@link Luhn#checkDigit(String) check digit} (0-9) over the digits of the owner's
56	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g. legacy seed
57	     * owners).
58	     */
59	    public static Integer checkDigit(Owner owner) {
60	        return owner.getCustomerCode() == null ? null : Luhn.checkDigit(owner.getCustomerCode());
61	    }
62	
63	    /**
64	     * First eight upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)} for the
65	     * owner — the HASH8 segment of the region-and-hash identity, independent of how that identity is
66	     * formatted.
67	     */
68	    public static String hash8(Owner owner) {
69	        return hash8(owner.getTelephone(), owner.getLastName());
70	    }
71	
72	    /**
73	     * The region for the owner: the region whose inclusive postcode range contains the owner's
74	     * postcode wins; otherwise the fixed city-to-region table ({@code Sydney->NSW, Melbourne->VIC,
75	     * Brisbane->QLD}); otherwise {@code "UNKNOWN"}.
76	     */
77	    public static String region(Owner owner) {
78	        String region = regionFromPostcode(owner.getPostcode());
79	        if (region != null) {
80	            return region;
81	        }
82	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
83	    }
84	
85	    /**
86	     * The REGION segment of a customer code (everything before the first {@code '-'}), or the whole
87	     * code when it contains no {@code '-'}. Returns {@code null} for a {@code null} code.
88	     */
89	    public static String regionOf(String customerCode) {
90	        if (customerCode == null) {
91	            return null;
92	        }
93	        int dash = customerCode.indexOf('-');
94	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
95	    }
96	
97	    /** First eight upper-case hex characters of {@code SHA-256(telephone + lastName)}. */
98	    private static String hash8(String telephone, String lastName) {
99	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
100	        MessageDigest digest;
101	        try {
102	            digest = MessageDigest.getInstance("SHA-256");
103	        }
104	        catch (NoSuchAlgorithmException ex) {
105	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
106	        }
107	        byte[] bytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
108	        StringBuilder hex = new StringBuilder(16);
109	        for (int i = 0; i < 4; i++) {
110	            hex.append(String.format("%02X", bytes[i]));
111	        }
112	        return hex.toString();
113	    }
114	
115	    /**
116	     * The region whose inclusive postcode range contains the given 4-digit postcode, or
117	     * {@code null} when the postcode is absent, non-numeric, or in no known range.
118	     */
119	    private static String regionFromPostcode(String postcode) {
120	        if (postcode == null || postcode.isBlank()) {
121	            return null;
122	        }
123	        int value;
124	        try {
125	            value = Integer.parseInt(postcode.trim());
126	        }
127	        catch (NumberFormatException ex) {
128	            return null;
129	        }
130	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
131	            int[] range = entry.getValue();
132	            if (value >= range[0] && value <= range[1]) {
133	                return entry.getKey();
134	            }
135	        }
136	        return null;
137	    }
138	}
