1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives the single {@code identityKey} that every owner duplicate check is expressed through: the
12	 * lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
13	 *
14	 * <p>Two owners are duplicates only when their WHOLE keys are equal. Because the normalized telephone
15	 * is part of the key, two owners with the same last name and postcode but DIFFERENT telephones have
16	 * different keys and are both allowed (they become a soft match instead — see
17	 * {@link AssignPossibleDuplicate}). The telephone is already normalized to E.164 and the email to
18	 * lower case by {@link BuildOwner}; the surname contributes its {@link Soundex} code so spelling
19	 * variants collapse together. A missing telephone or email contributes an empty segment.
20	 */
21	public final class OwnerIdentity {
22	
23	    private OwnerIdentity() {
24	    }
25	
26	    public static String key(Owner owner) {
27	        String input = segment(owner.getTelephone()) + '|' + lower(owner.getEmail()) + '|'
28	                + Soundex.of(owner.getLastName());
29	        try {
30	            byte[] digest = MessageDigest.getInstance("SHA-256")
31	                    .digest(input.getBytes(StandardCharsets.UTF_8));
32	            StringBuilder sb = new StringBuilder(digest.length * 2);
33	            for (byte b : digest) {
34	                sb.append(String.format("%02x", b));
35	            }
36	            return sb.toString();
37	        }
38	        catch (NoSuchAlgorithmException e) {
39	            throw new IllegalStateException("SHA-256 not available", e);
40	        }
41	    }
42	
43	    private static String segment(String value) {
44	        return value == null || value.isBlank() ? "" : value;
45	    }
46	
47	    private static String lower(String value) {
48	        return value == null || value.isBlank() ? "" : value.toLowerCase(Locale.ROOT);
49	    }
50	}
