1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * The Luhn check-digit algorithm over the digits contained in a string. Non-digit characters are
5	 * ignored, so it applies unchanged to a mixed code (letters and digits) as well as a bare number.
6	 *
7	 * <p>Implemented in-house (rather than pulling in a codec dependency) so the algorithm is fixed and
8	 * self-contained, mirroring {@link Soundex}. It is the single definition every code that carries a
9	 * trailing check digit hangs off — the {@code customerCode}'s {@code checkDigit} today.
10	 */
11	public final class Luhn {
12	
13	    private Luhn() {
14	    }
15	
16	    /** The Luhn check digit (0-9) computed over the digits contained in {@code value}. */
17	    public static int checkDigit(String value) {
18	        int sum = 0;
19	        boolean dbl = true;
20	        for (int i = value.length() - 1; i >= 0; i--) {
21	            char c = value.charAt(i);
22	            if (c < '0' || c > '9') {
23	                continue;
24	            }
25	            int d = c - '0';
26	            if (dbl) {
27	                d *= 2;
28	                if (d > 9) {
29	                    d -= 9;
30	                }
31	            }
32	            sum += d;
33	            dbl = !dbl;
34	        }
35	        return (10 - (sum % 10)) % 10;
36	    }
37	}
