1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year arithmetic for the owner's date-derived values. The fiscal year starts on 1 July, so
7	 * a date in July through December belongs to the fiscal year named by the <em>following</em>
8	 * calendar year (the year the fiscal year ends in). Everything date-derived — the {@code fiscalYear}
9	 * label, the membership number's year segment and tenure — hangs off this single definition.
10	 */
11	public final class FiscalYears {
12	
13	    private FiscalYears() {
14	    }
15	
16	    /**
17	     * The fiscal year containing {@code date}, named by the calendar year the fiscal year ends in.
18	     * The fiscal year runs 1 July to 30 June, so July-December fall in {@code year + 1} and
19	     * January-June fall in {@code year} (e.g. 2026-09-06 -> 2027, 2026-03-01 -> 2026).
20	     */
21	    public static int of(LocalDate date) {
22	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
23	    }
24	
25	    /** The {@code FY<YY>} label for {@code date}'s fiscal year (last two digits, e.g. 'FY27'). */
26	    public static String label(LocalDate date) {
27	        return String.format("FY%02d", of(date) % 100);
28	    }
29	
30	    /**
31	     * Whole fiscal years elapsed from {@code start} to {@code end}: the fiscal year of {@code end}
32	     * minus the fiscal year of {@code start}. A date and any later date within the same fiscal year
33	     * yield 0.
34	     */
35	    public static int elapsed(LocalDate start, LocalDate end) {
36	        return of(end) - of(start);
37	    }
38	}
