1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.OptionalInt;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Derives the owner's loyalty standing, exposed as two fields the create audit line and the owner
11	 * response both hang off: {@code membershipPoints} (the raw score) and {@code membershipLevel} (the
12	 * grade the points bucket into).
13	 *
14	 * <p>Points start at 0 and accumulate from the owner's factors: {@link #EMAIL_POINTS} for a present
15	 * email address, {@link #NO_NAMESAKE_POINTS} when {@code namesakeCount} is 0,
16	 * {@link #LARGE_HOUSEHOLD_POINTS} for a household of {@link #LARGE_HOUSEHOLD_SIZE} or more, and
17	 * {@link #TENURE_POINTS} for more than {@link #TENURE_FISCAL_YEARS_FOR_POINTS} elapsed fiscal
18	 * year(s) of tenure since {@code registrationDate}, where fiscal years start on 1 July (see
19	 * {@link FiscalYears}). A freshly created owner registers as of today and so has zero tenure.
20	 *
21	 * <p>Points map to a level of 1 (0-1 points), 2 (2-3), 3 (4-5) or 4 (6 or more).
22	 */
23	public final class Memberships {
24	
25	    /** Points awarded for a present (non-blank) email address. */
26	    private static final int EMAIL_POINTS = 2;
27	
28	    /** Points awarded when the owner has no namesakes ({@code namesakeCount == 0}). */
29	    private static final int NO_NAMESAKE_POINTS = 1;
30	
31	    /** Points awarded for belonging to a household of {@link #LARGE_HOUSEHOLD_SIZE} or more. */
32	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
33	
34	    /** Household size (members inclusive) at which {@link #LARGE_HOUSEHOLD_POINTS} is awarded. */
35	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
36	
37	    /** Points awarded for more than {@link #TENURE_FISCAL_YEARS_FOR_POINTS} elapsed fiscal years of tenure. */
38	    private static final int TENURE_POINTS = 3;
39	
40	    /** Elapsed fiscal years of tenure that must be exceeded to earn {@link #TENURE_POINTS}. */
41	    private static final int TENURE_FISCAL_YEARS_FOR_POINTS = 1;
42	
43	    /**
44	     * How far above the current household maximum a newly joining member's {@code membershipLevel}
45	     * may sit: at most one level higher (see {@link #cappedLevel(Owner, OwnerRepository)}).
46	     */
47	    private static final int LEVEL_CEILING_ABOVE_HOUSEHOLD_MAX = 1;
48	
49	    private Memberships() {
50	    }
51	
52	    /**
53	     * The owner's {@code membershipPoints}: the raw loyalty score built from a present email, no
54	     * namesakes, a large household and tenure. {@code householdSize} is the number of owners sharing
55	     * this owner's household (members inclusive).
56	     */
57	    public static int membershipPoints(Owner owner, long householdSize) {
58	        int points = 0;
59	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
60	        if (hasEmail) {
61	            points += EMAIL_POINTS;
62	        }
63	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
64	        if (noNamesakes) {
65	            points += NO_NAMESAKE_POINTS;
66	        }
67	        if (householdSize >= LARGE_HOUSEHOLD_SIZE) {
68	            points += LARGE_HOUSEHOLD_POINTS;
69	        }
70	        if (hasTenureForPoints(owner)) {
71	            points += TENURE_POINTS;
72	        }
73	        return points;
74	    }
75	
76	    /**
77	     * The owner's {@code membershipLevel}: the grade {@code membershipPoints} buckets into — 1 for
78	     * 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
79	     */
80	    public static int membershipLevel(int points) {
81	        if (points <= 1) {
82	            return 1;
83	        }
84	        if (points <= 3) {
85	            return 2;
86	        }
87	        if (points <= 5) {
88	            return 3;
89	        }
90	        return 4;
91	    }
92	
93	    /**
94	     * The owner's {@code membershipLevel} after applying the household level ceiling: a member's
95	     * level cannot exceed one above the current maximum {@code membershipLevel} among the household
96	     * members that already existed when this owner joined (those sharing its {@code householdId} with
97	     * a lower id, soft-deleted owners excluded). When the owner had no existing household member the
98	     * uncapped level stands. The comparison uses each existing member's own capped level, so the
99	     * ceiling holds transitively down the household.
100	     */
101	    public static int cappedLevel(Owner owner, OwnerRepository repository) {
102	        int uncapped = membershipLevel(membershipPoints(owner, Households.size(owner, repository)));
103	        String householdId = owner.getHouseholdId();
104	        Integer id = owner.getId();
105	        if (householdId == null || id == null) {
106	            return uncapped;
107	        }
108	        OptionalInt householdMax = repository.findAll().stream()
109	                .filter(existing -> existing.getId() != null && existing.getId() < id)
110	                .filter(existing -> householdId.equals(existing.getHouseholdId()))
111	                .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()))
112	                .mapToInt(existing -> cappedLevel(existing, repository))
113	                .max();
114	        if (householdMax.isEmpty()) {
115	            return uncapped;
116	        }
117	        return Math.min(uncapped, householdMax.getAsInt() + LEVEL_CEILING_ABOVE_HOUSEHOLD_MAX);
118	    }
119	
120	    private static boolean hasTenureForPoints(Owner owner) {
121	        LocalDate registrationDate = owner.getRegistrationDate();
122	        if (registrationDate == null) {
123	            return false;
124	        }
125	        int tenureFiscalYears = FiscalYears.elapsed(registrationDate, LocalDate.now());
126	        return tenureFiscalYears > TENURE_FISCAL_YEARS_FOR_POINTS;
127	    }
128	}
