1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Emits, once the owner has been persisted, both a human-readable audit line and an immutable
11	 * structured {@link OwnerCreatedEvent} to the dedicated {@code AUDIT} logger. The line records the
12	 * assigned id, the {@code customerCode}, the {@code registrationDate}, the {@code membershipPoints},
13	 * the {@code membershipLevel} and the {@code membershipNumber}; the event carries the sequence, the
14	 * owner id, the primary identifier and the membership level as JSON.
15	 */
16	public class AuditOwnerCreated {
17	
18	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        int points = Memberships.membershipPoints(owner, Households.size(owner, ownerRepository));
22	        int level = Memberships.cappedLevel(owner, ownerRepository);
23	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipPoints={} "
24	                + "membershipLevel={} membershipNumber={}",
25	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
26	                points, level, CustomerCodes.membershipNumber(owner));
27	        AUDIT.info("{}", OwnerCreatedEvent.next(owner, level).toJson());
28	    }
29	}
