1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	import tools.jackson.databind.json.JsonMapper;
8	
9	/**
10	 * Immutable structured audit event emitted once an owner has been created, alongside the
11	 * human-readable audit line. It is serialized to a JSON object
12	 * {@code {seq, ownerId, customerCode, membershipLevel, event}} on the dedicated {@code AUDIT}
13	 * logger (see {@link AuditOwnerCreated}).
14	 *
15	 * <p>{@code seq} is a monotonically increasing integer allocated across every create for the life
16	 * of the application (see {@link #SEQUENCE}). The event carries the owner's <em>current primary
17	 * identifier</em> — the {@code customerCode} today. That choice lives in one place,
18	 * {@link #primaryIdentifier(Owner)}: when the customer code is later unified into the memberId,
19	 * return the memberId there and the event carries the memberId instead.
20	 */
21	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, int membershipLevel,
22	        String event) {
23	
24	    /** The single kind of event this record represents. */
25	    public static final String OWNER_CREATED = "OWNER_CREATED";
26	
27	    /** Application-wide source of the monotonically increasing {@code seq}, shared across creates. */
28	    private static final AtomicLong SEQUENCE = new AtomicLong();
29	
30	    private static final JsonMapper JSON = JsonMapper.builder().build();
31	
32	    /**
33	     * The next event for {@code owner}, allocating the next {@code seq} from the shared
34	     * application-wide sequence. {@code membershipLevel} is the owner's capped membership level.
35	     */
36	    public static OwnerCreatedEvent next(Owner owner, int membershipLevel) {
37	        return new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
38	                primaryIdentifier(owner), membershipLevel, OWNER_CREATED);
39	    }
40	
41	    /**
42	     * The owner's current primary identifier carried by the event: the {@code customerCode} today.
43	     * When the customer code is unified into the memberId, return the memberId here so the event
44	     * carries it instead — the single place that choice lives.
45	     */
46	    private static String primaryIdentifier(Owner owner) {
47	        return owner.getCustomerCode();
48	    }
49	
50	    /** This event as its JSON object form, for the {@code AUDIT} logger. */
51	    public String toJson() {
52	        return JSON.writeValueAsString(this);
53	    }
54	}
